"use strict";(self.webpackChunkfrontend=self.webpackChunkfrontend||[]).push([[805],{90805(e,n,i){i.d(n,{FT:()=>s,OD:()=>a,lQ:()=>u});var t=i(89379);const r=function(e,n,i,r){let s=arguments.length>5&&void 0!==arguments[5]?arguments[5]:{};return{slug:e,title:n,intro:i,sections:r,faqs:arguments.length>4&&void 0!==arguments[4]?arguments[4]:[],meta:(0,t.A)({title:"".concat(n," | Fr\xf6hlich Verm\xf6gensberatung"),description:s.description||i.slice(0,155)},s)}},s=[{slug:"anlagestile",title:"Anlagestile",eyebrow:"Anlagestile",icon:"trending-up",lede:"Zwei ausgew\xe4hlte Anlagestile: analytisch gepr\xe4gtes Value Investing und ertragsorientierte Dividendenstrategien.",intro:"Anlagestile beschreiben, nach welchen Prinzipien Wertpapiere ausgew\xe4hlt und im Portfolio gehalten werden. Sie geben Ihrem Investieren Struktur \u2014 und machen Entscheidungen nachvollziehbar.",topics:[r("value-investing","Value Investing","Value Investing bezeichnet einen Anlagestil, der gezielt Unternehmen sucht, deren B\xf6rsenwert aus Sicht des Anlegers unter dem inneren Wert liegt. Ziel ist eine Sicherheitsmarge: der Kaufpreis soll niedriger sein als eine sachlich hergeleitete Bewertung.",[{heading:"Was bedeutet das?",body:'Value Investing geht auf Benjamin Graham und David Dodd zur\xfcck und wurde sp\xe4ter besonders durch Warren Buffett bekannt. Die Grundidee: Der Markt ist kurzfristig oft emotional, langfristig aber ein \u201eWiegemeister" \u2014 der innere Wert eines Unternehmens setzt sich mit der Zeit durch.'},{heading:"Wie funktioniert die Strategie?",body:["Ausgangspunkt ist eine Fundamentalanalyse: Bilanz, Cashflow, Wettbewerbsposition, Verschuldung und Managementqualit\xe4t werden bewertet.","Der gesch\xe4tzte innere Wert wird mit dem aktuellen B\xf6rsenkurs verglichen.",'Ein Kauf kommt nur infrage, wenn der Marktpreis deutlich unter dem inneren Wert liegt (\u201emargin of safety").',"Positionen werden in der Regel \xfcber Jahre gehalten, bis der Markt den Wert reflektiert oder sich die These ver\xe4ndert."]},{heading:"F\xfcr wen kann sie interessant sein?",body:"F\xfcr Anlegerinnen und Anleger mit langem Atem, ausgepr\xe4gter Preissensibilit\xe4t und Bereitschaft, gegen den kurzfristigen Konsens zu investieren. Value Investing eignet sich weniger f\xfcr kurzfristige Handelsans\xe4tze."},{heading:"Welche Chancen bestehen?",body:"\xdcber lange Zeitr\xe4ume hat sich der Ansatz akademisch h\xe4ufig als robust gezeigt. Sollte der Markt den inneren Wert einpreisen, kann sich die anf\xe4ngliche Bewertungsl\xfccke schlie\xdfen."},{heading:"Welche Risiken und Nachteile gibt es?",body:["Value-Fallen: Ein niedrig bewertetes Unternehmen kann strukturell in einem strauchelnden Gesch\xe4ftsmodell stecken.","Lange Wartezeiten: Der Markt braucht mitunter Jahre, bis Bewertungsl\xfccken schlie\xdfen.","Prozykliker: In sehr wachstumsorientierten Marktphasen kann Value gegen\xfcber Growth relativ zur\xfcckbleiben."]},{heading:"Rolle in einem diversifizierten Portfolio",body:"Value erg\xe4nzt Wachstums- und Trendstrategien und kann in Marktphasen mit steigenden Zinsen oder Bewertungsdruck stabilisierend wirken. In der Regel wird Value nur als ein Baustein neben anderen Anlageklassen und Stilen genutzt."},{heading:"Worauf sollte man achten?",body:"Auf klare Auswahlkriterien, Diversifikation \xfcber Branchen und Regionen, Kostenstruktur bei Fonds/ETFs und darauf, dass die eigene Halte-Dauer zur Strategie passt."}],[{q:"Ist Value Investing veraltet?",a:"Nein. Bewertungsorientierte Ans\xe4tze bleiben ein etablierter Teil der Anlagelehre. Sie durchlaufen aber Phasen, in denen sie sich schw\xe4cher entwickeln als wachstumsbetonte Stile."},{q:"Kann ich Value Investing \xfcber ETFs abbilden?",a:"Ja, es gibt Faktor-ETFs, die systematisch nach Bewertungskennzahlen selektieren. Alternativ existieren aktiv gemanagte Value-Fonds mit unterschiedlichen Auslegungen."},{q:"Wie lange sollte ich Value-Positionen halten?",a:"Value entfaltet seine Idee typischerweise \xfcber mehrj\xe4hrige Zeitr\xe4ume. Ein Anlagehorizont von unter drei Jahren passt selten zum Stil."}],{description:"Value Investing verst\xe4ndlich erkl\xe4rt: Grundidee, Vorgehen, Chancen und Risiken sowie die Rolle in einem diversifizierten Portfolio."}),r("dividendenstrategien","Dividendenstrategien","Dividendenstrategien konzentrieren sich auf Unternehmen, die einen Teil ihres Gewinns regelm\xe4\xdfig aussch\xfctten. Im Vordergrund stehen laufende Ertr\xe4ge, verl\xe4ssliche Aussch\xfcttungspolitik und die Qualit\xe4t des zugrundeliegenden Gesch\xe4ftsmodells.",[{heading:"Was bedeutet das?",body:"Statt allein auf Kursgewinne zu setzen, wird ein Teil der erwarteten Gesamtrendite in Form von Dividenden vereinnahmt. Wer regelm\xe4\xdfige Aussch\xfcttungen bevorzugt oder Cashflow-Aspekte betont, findet in Dividendenstrategien einen konsistenten Rahmen."},{heading:"Wie funktioniert die Strategie?",body:["Auswahl von Unternehmen mit stabiler oder wachsender Aussch\xfcttung.","Pr\xfcfung der Aussch\xfcttungsquote \u2014 nicht jede hohe Rendite ist tragf\xe4hig.","Betrachtung der Bilanzqualit\xe4t, Verschuldung und der Nachhaltigkeit des Cashflows.","Streuung \xfcber Sektoren und Regionen, um Klumpenrisiken zu vermeiden."]},{heading:"F\xfcr wen kann sie interessant sein?",body:"F\xfcr Anlegerinnen und Anleger, die laufende Zahlungsstr\xf6me wertsch\xe4tzen oder einen ruhigeren Renditepfad bevorzugen. H\xe4ufig genutzt im Zusammenhang mit Aussch\xfcttungspl\xe4nen f\xfcr die Ruhestandsphase."},{heading:"Welche Chancen bestehen?",body:"Laufende Ertr\xe4ge unabh\xe4ngig vom Kursverlauf, h\xe4ufig geringere Schwankungen bei etablierten Dividendenzahlern und ein sichtbarer Cashflow-Beitrag zur Gesamtrendite."},{heading:"Welche Risiken und Nachteile gibt es?",body:["K\xfcrzungen oder Aussetzungen sind m\xf6glich, insbesondere in Krisen.","Hohe Dividendenrenditen sind manchmal ein Warnsignal \u2014 nicht immer ein Vorteil.","Steuerliche Behandlung von Dividenden kann Renditen relativ zu reinen Kursgewinnen beeinflussen."]},{heading:"Rolle in einem diversifizierten Portfolio",body:"Dividendenstrategien werden h\xe4ufig als aussch\xfcttungsorientierter Baustein neben wachstumsbetonten Positionen genutzt und k\xf6nnen den aussch\xfcttungsgetriebenen Cashflow eines Depots erh\xf6hen."},{heading:"Worauf sollte man achten?",body:"Auf die Qualit\xe4t der Aussch\xfcttung (nicht nur H\xf6he), auf die Verteilung \xfcber Branchen und darauf, wie Aussch\xfcttungen in der eigenen Steuersituation wirken."}],[{q:"Ist eine hohe Dividendenrendite immer gut?",a:"Nicht zwangsl\xe4ufig. Ein sehr hoher Wert kann auf einen stark gefallenen Kurs oder eine kaum tragf\xe4hige Aussch\xfcttung hindeuten."},{q:"Passen Dividendenstrategien zu j\xfcngeren Anlegern?",a:"Sie k\xf6nnen erg\xe4nzend passen, sind aber selten der einzige Baustein \u2014 Wachstumsanteile sind bei langem Horizont typischerweise ebenfalls sinnvoll."}],{description:"Dividendenstrategien verst\xe4ndlich: Idee, Auswahlkriterien, Chancen, Risiken und Rolle im Portfolio."})]},{slug:"nachhaltigkeit",title:"Nachhaltigkeit",eyebrow:"Nachhaltigkeit",icon:"leaf",lede:"Anlagen, die \xf6kologische, soziale und Governance-Aspekte konsequent mitdenken.",intro:"Nachhaltiges Investieren verbindet finanzielle Ziele mit Werten. Die Ans\xe4tze reichen von klassischer ESG-Integration bis zu Impact-Investments mit klar messbarem Wirkungsziel.",topics:[r("nachhaltige-investments-esg","Nachhaltige Investments (ESG)","ESG steht f\xfcr Environment (Umwelt), Social (Soziales) und Governance (Unternehmensf\xfchrung). Nachhaltige Investments ber\xfccksichtigen diese Kriterien systematisch bei der Auswahl von Wertpapieren.",[{heading:"Was bedeutet das?",body:"ESG-Investing ist ein Sammelbegriff f\xfcr unterschiedliche Verfahren: Ausschlusskriterien (bestimmte Branchen ausschlie\xdfen), Best-in-Class (die nachhaltigsten Unternehmen einer Branche bevorzugen), Integration (ESG-Kennzahlen in die Fundamentalanalyse einflie\xdfen lassen) sowie Impact-Ans\xe4tze mit messbarem Ziel."},{heading:"Wie funktioniert die Strategie?",body:["Definition der eigenen Priorit\xe4ten (z. B. Klima, Menschenrechte, Governance).","Auswahl passender Fonds/ETFs bzw. Direktinvestments.","Pr\xfcfung der zugrundeliegenden Methodik \u2014 Ratings unterscheiden sich je Anbieter.","Regelm\xe4\xdfige \xdcberpr\xfcfung, ob die Anlage tats\xe4chlich die gesetzten Kriterien erf\xfcllt."]},{heading:"F\xfcr wen kann sie interessant sein?",body:"F\xfcr Anlegerinnen und Anleger, die finanzielle Ziele mit einem klaren Wertekompass verbinden m\xf6chten und bereit sind, sich mit unterschiedlichen Methodiken auseinanderzusetzen."},{heading:"Welche Chancen bestehen?",body:"ESG-Themen wie Energiewende, Digitalisierung und Ressourceneffizienz sind langfristige Wachstumsfelder. Zudem gewinnen Regulierung und Berichtspflichten an Bedeutung, was Transparenz und Vergleichbarkeit erh\xf6ht."},{heading:"Welche Risiken und Nachteile gibt es?",body:['\u201eGreenwashing" \u2014 Produkte tragen nachhaltige Etiketten, ohne die Kriterien substanziell zu erf\xfcllen.',"Uneinheitliche Ratings: verschiedene Anbieter bewerten Unternehmen unterschiedlich.","Konzentrationsrisiken, wenn Portfolios auf wenige nachhaltige Sektoren fokussieren."]},{heading:"Rolle in einem diversifizierten Portfolio",body:"ESG-Investments lassen sich als Kern- oder Erg\xe4nzungsbaustein einsetzen und k\xf6nnen mit klassischen Anlagestilen kombiniert werden. Eine bewusste Streuung bleibt entscheidend."},{heading:"Worauf sollte man achten?",body:"Auf die Methodik hinter dem Label (Art. 6/8/9-SFDR), die zugrundeliegenden Ratings, die Portfolio-Zusammensetzung und die Gesamtkosten des Vehikels."}],[{q:"Bringt ESG automatisch weniger Rendite?",a:"Empirisch ist der Zusammenhang uneinheitlich. In manchen Phasen liegen ESG-Portfolios vorne, in anderen nicht. Entscheidend sind Methodik, Kostenstruktur und Marktumfeld."},{q:"Ist Art. 9 immer nachhaltiger als Art. 8?",a:"Art. 9-Fonds verfolgen ein nachhaltiges Anlageziel als Kern, Art. 8-Fonds ber\xfccksichtigen ESG-Aspekte. Ob ein Fonds zu Ihnen passt, h\xe4ngt vom konkreten Ansatz ab, nicht allein vom Label."}],{description:"ESG-Investing verst\xe4ndlich: Methoden, Chancen, Risiken und wie sich Nachhaltigkeit im Portfolio abbilden l\xe4sst."}),r("impact-investing","Impact Investing","Impact Investing zielt bewusst darauf, neben einer finanziellen Rendite eine messbare positive Wirkung auf Umwelt oder Gesellschaft zu erreichen \u2014 vom Sozialwohnungsbau bis zu Klimaprojekten.",[{heading:"Was bedeutet das?",body:"Anders als reines ESG-Investing verlangt Impact-Investing eine explizite Wirkungsabsicht und ein Messkonzept. Die Anlage soll ein klar definiertes Umwelt- oder Sozialziel unterst\xfctzen."},{heading:"Wie funktioniert die Strategie?",body:["Festlegung des Wirkungsziels (z. B. Reduktion von CO\u2082, Zugang zu Bildung).","Auswahl von Anlagevehikeln, die dieses Ziel adressieren (Fonds, Genossenschaftsanteile, Themen-Aktien, Green Bonds).","Messung anhand definierter Kennzahlen (z. B. eingesparte Tonnen CO\u2082, versorgte Haushalte).","Regelm\xe4\xdfige Berichte zur Wirkungs- und Finanzperformance."]},{heading:"F\xfcr wen kann sie interessant sein?",body:"F\xfcr Anleger, die einen expliziten Beitrag \xfcber die reine Kapitalallokation hinaus leisten m\xf6chten und akzeptieren, dass Wirkung Zeit braucht und selten linear verl\xe4uft."},{heading:"Welche Chancen bestehen?",body:"Zugang zu Zukunftsthemen wie erneuerbare Energien, nachhaltige Infrastruktur oder Bildungsangebote. In vielen Bereichen bestehen langfristige gesellschaftliche und regulatorische R\xfcckenwinde."},{heading:"Welche Risiken und Nachteile gibt es?",body:["Einige Impact-Anlagen sind weniger liquide und langfristig gebunden.","Wirkungsmessung ist methodisch anspruchsvoll und nicht immer vergleichbar.","Ergebnisorientierte Themen k\xf6nnen projekt- oder l\xe4nderspezifischen Risiken unterliegen."]},{heading:"Rolle in einem diversifizierten Portfolio",body:"Impact-Investments werden h\xe4ufig als thematische Erg\xe4nzung eingesetzt, ohne den Diversifikationsgedanken aufzugeben. Sie ersetzen nicht die Portfoliostruktur, sondern sch\xe4rfen sie inhaltlich."},{heading:"Worauf sollte man achten?",body:"Auf die konkrete Wirkungsmessung, Laufzeiten, Liquidit\xe4t, Anbieterqualit\xe4t sowie darauf, dass die Anlage Teil eines Gesamtplans bleibt."}],[{q:"Ist Impact-Investing dasselbe wie Spende?",a:"Nein. Impact-Investing verfolgt weiterhin eine finanzielle Rendite, verbindet sie aber mit einer klaren, messbaren Wirkungsabsicht."}],{description:"Impact Investing erkl\xe4rt: klare Wirkungsabsicht, Messkonzepte, Chancen und Risiken."})]},{slug:"schutz-steuerung",title:"Schutz & Steuerung",eyebrow:"Schutz & Steuerung",icon:"shield",lede:"Kernstrategien, um Verm\xf6gen zu erhalten, gegen Kaufkraftverluste zu wappnen und strukturiert aufzubauen.",intro:"Die drei Bausteine dieser Kategorie greifen ineinander: Verm\xf6gensschutz sichert das Erreichte, Inflationsschutz erh\xe4lt die Kaufkraft, Verm\xf6gensaufbau setzt neuen Boden.",topics:[r("vermoegensschutz","Verm\xf6gensschutz","Verm\xf6gensschutz zielt darauf, bereits Erreichtes zu bewahren \u2014 vor Marktrisiken, unerwarteten Ereignissen und rechtlichen Risiken. Es ist die Basisdisziplin einer langfristigen Verm\xf6gensplanung.",[{heading:"Was bedeutet das?",body:"Verm\xf6gensschutz ist mehr als eine einzelne Anlagestrategie. Er umfasst Portfoliostreuung, Auswahl geeigneter Rechtsformen, Absicherung bestimmter Lebensrisiken und die klare Trennung von privatem und betrieblichem Verm\xf6gen."},{heading:"Wie funktioniert die Strategie?",body:["Bestandsaufnahme aller Verm\xf6genswerte \u2014 inklusive Immobilien, Depots, Beteiligungen und Verbindlichkeiten.","Identifikation von Klumpen- und Konzentrationsrisiken.","Diversifikation \xfcber Anlageklassen, Regionen, W\xe4hrungen und Zugriffsrechte.","Abstimmung mit steuerlichen und rechtlichen Rahmenbedingungen."]},{heading:"F\xfcr wen kann sie interessant sein?",body:"F\xfcr alle, die bereits Verm\xf6gen aufgebaut haben oder auf einen wichtigen Lebensabschnitt (z. B. Ruhestand, \xdcbertragung) zusteuern und Stabilit\xe4t st\xe4rker gewichten als maximales Wachstum."},{heading:"Welche Chancen bestehen?",body:"Reduzierung gro\xdfer Verlustrisiken, Erhalt handlungsf\xe4higer Reserven in Krisen und Sicherung des Erreichten f\xfcr die n\xe4chste Lebensphase."},{heading:"Welche Risiken und Nachteile gibt es?",body:["\xdcbertriebener Fokus auf Sicherheit kann Renditepotenziale mindern.","Manche Absicherungsl\xf6sungen (z. B. Versicherungsm\xe4ntel) sind komplex und kostenintensiv.","Reine Cash-L\xf6sungen bergen ihrerseits Kaufkraftrisiken."]},{heading:"Rolle in einem diversifizierten Portfolio",body:"Verm\xf6gensschutz ist selten eine einzelne Position, sondern eine \xfcbergeordnete Denkweise: Diversifikation, Liquidit\xe4tsreserve und rechtlich saubere Strukturen greifen ineinander."},{heading:"Worauf sollte man achten?",body:"Auf Gesamtsicht statt Einzelprodukt, auf Kosten, auf steuerliche Wirkung und darauf, dass Absicherung und Rendite in einem sinnvollen Verh\xe4ltnis stehen."}]),r("inflationsschutz","Inflationsschutz","Inflation entwertet Guthaben, deren Verzinsung dauerhaft unter der Teuerung liegt. Ein Inflationsschutz-Ansatz zielt darauf, Kaufkraft \xfcber die Zeit zu erhalten.",[{heading:"Was bedeutet das?",body:"Inflationsschutz ist kein einzelnes Produkt, sondern eine Mischung aus realwerten Anlagen und geeigneten Zinsstrukturen. Ziel ist es, dass die Anlage im Idealfall mit der Teuerung mitl\xe4uft oder dar\xfcber liegt."},{heading:"Wie funktioniert die Strategie?",body:["Anteil an Sachwerten wie Aktien, Immobilien oder Rohstoffen pr\xfcfen.","Inflationsindexierte Anleihen (z. B. Bundes-Linker) einordnen.","Zinsniveau der Cash-Reserven pr\xfcfen und flexibel reagieren.","Regelm\xe4\xdfig gegen die tats\xe4chliche Inflationsrate spiegeln."]},{heading:"F\xfcr wen kann sie interessant sein?",body:"F\xfcr Sparer und Investoren, die l\xe4ngerfristig planen und die Erosion der Kaufkraft aktiv adressieren wollen \u2014 insbesondere in Phasen erh\xf6hter Inflation."},{heading:"Welche Chancen bestehen?",body:"Kaufkrafterhalt, potenzielle Zusatzertr\xe4ge \xfcber den Nominalzinsen, und stabiler Realwert der Anlage."},{heading:"Welche Risiken und Nachteile gibt es?",body:["Sachwerte k\xf6nnen erheblich schwanken.","Inflationsindexierte Anleihen haben eigene Kursrisiken und Deflationsrisiken.","Kein Baustein garantiert Kaufkrafterhalt in jeder Marktlage."]},{heading:"Rolle in einem diversifizierten Portfolio",body:"Ein Inflationsschutz-Baustein wirkt erg\xe4nzend zu einem gestreuten Kernportfolio und richtet sich am Zeithorizont sowie an der eigenen Ausgabenstruktur aus."},{heading:"Worauf sollte man achten?",body:"Auf den realen Zinsanteil, auf Kosten und Steuern der eingesetzten Vehikel und darauf, dass Cash-Reserven nicht zu gro\xdf werden."}]),r("vermoegensaufbau","Verm\xf6gensaufbau","Verm\xf6gensaufbau ist die schrittweise, langfristige Vermehrung von Kapital \u2014 meist \xfcber Sparraten in einem gut diversifizierten Portfolio. Zinseszinseffekte und Disziplin sind wesentliche Hebel.",[{heading:"Was bedeutet das?",body:"Verm\xf6gensaufbau steht am Anfang jeder Verm\xf6gensplanung. Er verbindet konkrete Sparraten mit einer Struktur, die zum eigenen Zeithorizont, zur Risikotragf\xe4higkeit und zu den Zielen passt."},{heading:"Wie funktioniert die Strategie?",body:["Ziele kl\xe4ren: Zeitraum, Wunschsumme, sp\xe4tere Verwendung.","Sparrate festlegen und automatisieren.","Anlagemix w\xe4hlen (z. B. ETF-Kern, erg\xe4nzende Bausteine).","Regelm\xe4\xdfig pr\xfcfen und schrittweise anpassen."]},{heading:"F\xfcr wen kann sie interessant sein?",body:"Grunds\xe4tzlich f\xfcr alle, die planen und mit realistischen Erwartungen langfristig sparen m\xf6chten \u2014 vom Berufseinstieg bis zur Familienphase und dar\xfcber hinaus."},{heading:"Welche Chancen bestehen?",body:"Zinseszinseffekt \xfcber die Zeit, Gl\xe4ttung von Marktschwankungen durch regelm\xe4\xdfige K\xe4ufe und ein bewusstes Kostenmanagement."},{heading:"Welche Risiken und Nachteile gibt es?",body:["Marktschwankungen k\xf6nnen zwischenzeitlich zu Buchverlusten f\xfchren.","Zu enge Timing-Versuche f\xfchren h\xe4ufig zu ung\xfcnstigen Kauf-/Verkaufsentscheidungen.","Zu geringe Sparraten oder unregelm\xe4\xdfiges Sparen verringern die Zieltreue."]},{heading:"Rolle in einem diversifizierten Portfolio",body:"Verm\xf6gensaufbau ist meist der Kern einer Verm\xf6gensplanung: er stellt die Basis, auf der sp\xe4tere Schutz- und \xdcbertragungsstrategien aufsetzen."},{heading:"Worauf sollte man achten?",body:"Auf Kosten, Streuung, Steuerthemen und die F\xe4higkeit, in Krisen bei der Strategie zu bleiben."}])]},{slug:"altersvorsorge",title:"Altersvorsorge",eyebrow:"Altersvorsorge",icon:"clock",lede:"Bausteine, um die sp\xe4tere Einkommensl\xfccke im Ruhestand zu schlie\xdfen \u2014 gesetzlich, privat und betrieblich.",intro:"Die Altersvorsorge st\xfctzt sich in Deutschland auf drei S\xe4ulen. Wir betrachten sie hier aus Anlegersicht \u2014 mit Fokus auf Planung, Flexibilit\xe4t und die tats\xe4chliche Ausgestaltung.",topics:[r("altersvorsorge","Altersvorsorge","Altersvorsorge beschreibt alle Ma\xdfnahmen, mit denen im sp\xe4teren Leben ein tragf\xe4higes Einkommen sichergestellt wird \u2014 von der gesetzlichen Rente \xfcber private Sparpl\xe4ne bis zu betrieblichen Zusagen.",[{heading:"Was bedeutet das?",body:"Zur Altersvorsorge geh\xf6ren staatliche Leistungen, privat aufgebaute Verm\xf6gen, betriebliche Zusatzversorgungen und in vielen F\xe4llen Immobilien oder Beteiligungen. Ziel ist ein tragf\xe4higer Mix aus laufendem Einkommen und Verm\xf6gensbestand."},{heading:"Wie funktioniert die Strategie?",body:["Analyse der voraussichtlichen Einkommensl\xfccke.","Pr\xfcfung der drei S\xe4ulen (gesetzlich, privat, betrieblich).","Wahl geeigneter Sparformen (Depots, Versicherungsl\xf6sungen, bAV).","Regelm\xe4\xdfige Anpassung an Lebensphasen und steuerliche \xc4nderungen."]},{heading:"F\xfcr wen kann sie interessant sein?",body:"F\xfcr alle. Wer fr\xfch startet, profitiert von Zeit; wer sp\xe4ter einsteigt, kann mit gezielter Strukturierung viel erreichen."},{heading:"Welche Chancen bestehen?",body:"Klar geplantes Einkommen im Ruhestand, steuerliche Effekte (z. B. bei bAV), Flexibilit\xe4t in der Verwendung und die M\xf6glichkeit, Kapital gestaffelt zu entnehmen."},{heading:"Welche Risiken und Nachteile gibt es?",body:["Zu geringes Sparen erh\xf6ht die Einkommensl\xfccke.","Falsche Produktauswahl kann teuer und wenig flexibel sein.","Politische und regulatorische \xc4nderungen wirken auf staatliche und betriebliche Elemente."]},{heading:"Rolle in einem diversifizierten Portfolio",body:"Altersvorsorge ist ein eigener Zweck im Verm\xf6gensplan. Sie steht neben freien Verm\xf6genswerten und sollte nicht mit kurzfristiger Liquidit\xe4t vermischt werden."},{heading:"Worauf sollte man achten?",body:"Auf Kosten, Flexibilit\xe4t, steuerliche Wirkung und die passende Verzahnung mit anderen Bausteinen des Verm\xf6gens."}]),r("private-rentenvorsorge","Private Rentenvorsorge","Die private Rentenvorsorge erg\xe4nzt gesetzliche und betriebliche Anspr\xfcche mit eigenem Kapital \u2014 h\xe4ufig \xfcber Fondssparpl\xe4ne, ETF-Depots oder Rentenversicherungen.",[{heading:"Was bedeutet das?",body:"Privat baut jede und jeder Verm\xf6gen f\xfcr den Ruhestand auf. Die Palette reicht vom flexiblen Wertpapierdepot bis zur klassischen Rentenversicherung mit lebenslangen Zahlungen."},{heading:"Wie funktioniert die Strategie?",body:["Ziele definieren: Zeitpunkt, H\xf6he, Verwendung.","Sparform w\xe4hlen (Depot vs. Versicherungsmantel).","Kostenstruktur der L\xf6sung pr\xfcfen.","Regelm\xe4\xdfig Sparrate und Portfoliostruktur \xfcberpr\xfcfen."]},{heading:"F\xfcr wen kann sie interessant sein?",body:"F\xfcr alle, die erg\xe4nzend zur gesetzlichen Rente Kapital aufbauen m\xf6chten und Flexibilit\xe4t sowie Kosten aktiv steuern wollen."},{heading:"Welche Chancen bestehen?",body:"Freie Wahl zwischen Kapital- und Rentenl\xf6sung, breite Produktvielfalt und die M\xf6glichkeit, Sparraten dynamisch anzupassen."},{heading:"Welche Risiken und Nachteile gibt es?",body:["Manche Versicherungsl\xf6sungen sind schwer vergleichbar und mit langen Bindungen versehen.","Wertpapierbasierte L\xf6sungen unterliegen Kursschwankungen.","Zu sp\xe4te Beitragsanpassungen k\xf6nnen Ziele verfehlen lassen."]},{heading:"Rolle in einem diversifizierten Portfolio",body:"Private Rentenvorsorge sollte in ein Gesamtbild eingebettet werden, das Liquidit\xe4t, Verm\xf6gensaufbau und Absicherung enth\xe4lt."},{heading:"Worauf sollte man achten?",body:"Auf Gesamtkosten, Flexibilit\xe4t in Beitragspausen/Entnahmen, steuerliche Behandlung und den Anlage-Kern der L\xf6sung."}]),r("betriebliche-altersvorsorge","Betriebliche Altersvorsorge","Die betriebliche Altersvorsorge (bAV) erg\xe4nzt die private Vorsorge \xfcber den Arbeitgeber. Sie ist h\xe4ufig steuerlich gef\xf6rdert und kann tarifliche oder betriebliche Zusch\xfcsse enthalten.",[{heading:"Was bedeutet das?",body:"Bei der bAV zahlen Besch\xe4ftigte einen Teil ihres Bruttogehalts in eine Versorgungsl\xf6sung ein. F\xfcnf Durchf\xfchrungswege existieren, u. a. Direktversicherung, Pensionskasse oder Unterst\xfctzungskasse."},{heading:"Wie funktioniert die Strategie?",body:["Pr\xfcfen, welche Durchf\xfchrungswege der Arbeitgeber anbietet.","H\xf6he und Steuerwirkung ermitteln (Entgeltumwandlung, Zusch\xfcsse).","Anlageform innerhalb der L\xf6sung w\xe4hlen, sofern m\xf6glich.","Bei Wechsel des Arbeitgebers Portabilit\xe4t pr\xfcfen."]},{heading:"F\xfcr wen kann sie interessant sein?",body:"F\xfcr sozialversicherungspflichtig Besch\xe4ftigte, insbesondere wenn der Arbeitgeber Zusch\xfcsse leistet oder tarifliche Modelle bestehen."},{heading:"Welche Chancen bestehen?",body:"Steuer- und sozialversicherungsrechtliche Effekte, Arbeitgeberzusch\xfcsse und ein organisierter, ratensparender Aufbau von Alterskapital."},{heading:"Welche Risiken und Nachteile gibt es?",body:["In der Auszahlungsphase fallen h\xe4ufig Sozialabgaben an.","Wechsel des Arbeitgebers erfordern eine sorgf\xe4ltige \xdcbernahme oder Beitragsfreistellung.","Manche Modelle sind wenig transparent oder starr."]},{heading:"Rolle in einem diversifizierten Portfolio",body:"Die bAV ist ein steuerlich gepr\xe4gter Baustein und erg\xe4nzt die private Vorsorge. Sie sollte im Zusammenspiel mit freien Anlagen und der gesetzlichen Rente betrachtet werden."},{heading:"Worauf sollte man achten?",body:"Auf Kosten, Zusch\xfcsse, Portabilit\xe4t, sp\xe4tere Sozialabgaben und die Anlagepolitik der L\xf6sung."}])]},{slug:"generationen",title:"Generationen",eyebrow:"Generationen",icon:"users",lede:"Verm\xf6gen \xfcber Lebensphasen hinweg denken \u2014 f\xfcr Kinder aufbauen, an die n\xe4chste Generation \xfcbergeben.",intro:"Verm\xf6gen entsteht selten in einer einzigen Lebensphase. Wer \xfcber Generationen plant, denkt Verm\xf6gensaufbau und \xdcbertragung gemeinsam \u2014 steuerlich, rechtlich und pers\xf6nlich.",topics:[r("vermoegensaufbau-fuer-kinder","Verm\xf6gensaufbau f\xfcr Kinder","Ein fr\xfch gestarteter, langfristiger Kapitalaufbau f\xfcr Kinder profitiert besonders vom Zeithorizont. Selbst kleinere Sparraten k\xf6nnen sich \xfcber zwei Jahrzehnte sp\xfcrbar entfalten.",[{heading:"Was bedeutet das?",body:"Verm\xf6gensaufbau f\xfcr Kinder ist ein zweckgebundener Sparprozess: Ausbildung, F\xfchrerschein, erste Wohnung \u2014 die Ziele variieren, die Struktur bleibt \xe4hnlich."},{heading:"Wie funktioniert die Strategie?",body:["Zielhorizont festlegen (typischerweise 10\u201320 Jahre).","Depotform w\xe4hlen (Kinderdepot auf Namen des Kindes vs. Depot der Eltern).","Sparrate automatisieren und breit streuen.","Steuerliche Freibetr\xe4ge und rechtliche Aspekte pr\xfcfen."]},{heading:"F\xfcr wen kann sie interessant sein?",body:"F\xfcr Eltern, Gro\xdfeltern oder Paten, die f\xfcr Kinder langfristig sparen und Zeit gezielt als Hebel nutzen m\xf6chten."},{heading:"Welche Chancen bestehen?",body:"Langer Anlagehorizont, Zinseszinseffekt, Nutzung steuerlicher Freibetr\xe4ge und ein solider Grundstock f\xfcr den Start ins Erwachsenenleben."},{heading:"Welche Risiken und Nachteile gibt es?",body:["Ein Depot auf den Namen des Kindes geh\xf6rt rechtlich dem Kind \u2014 R\xfcckgriff ist eingeschr\xe4nkt.","Marktschwankungen sind \xfcber lange Zeitr\xe4ume \xfcblich; Panikreaktionen k\xf6nnen Ziele gef\xe4hrden.","Zu geringe Sparraten reichen bei hohen Zielsummen nicht."]},{heading:"Rolle in einem diversifizierten Portfolio",body:"Ein eigenst\xe4ndiger Baustein f\xfcr ein klar definiertes Ziel \u2014 bewusst getrennt vom allgemeinen Verm\xf6gensaufbau der Eltern."},{heading:"Worauf sollte man achten?",body:"Auf Kosten, Streuung, Zugriffsrecht, steuerliche Freibetr\xe4ge und darauf, dass der Anlagehorizont zum Ziel passt."}]),r("vermoegensuebertragung","Verm\xf6gens\xfcbertragung","Die geordnete \xdcbertragung von Verm\xf6gen \u2014 zu Lebzeiten oder im Erbfall \u2014 schafft Klarheit f\xfcr die n\xe4chste Generation und vermeidet vermeidbare Kosten oder Konflikte.",[{heading:"Was bedeutet das?",body:"Verm\xf6gens\xfcbertragung umfasst Schenkungen, Erbschaften, Nie\xdfbrauch, Familienstiftungen und andere Instrumente. Ziel ist ein \xdcbergang, der zu Familien- und Steuersituation passt."},{heading:"Wie funktioniert die Strategie?",body:["Bestandsaufnahme des Verm\xf6gens.","Kl\xe4rung der W\xfcnsche innerhalb der Familie.","Pr\xfcfung von Freibetr\xe4gen, Bewertungsmethoden und Steuerklassen.","Rechtliche Gestaltung mit Notar/Steuerberater \u2014 inklusive Testament oder Erbvertrag."]},{heading:"F\xfcr wen kann sie interessant sein?",body:"F\xfcr alle, die ihre sp\xe4tere Nachfolge aktiv gestalten m\xf6chten \u2014 insbesondere bei gr\xf6\xdferem Verm\xf6gen, Familienunternehmen oder Patchwork-Konstellationen."},{heading:"Welche Chancen bestehen?",body:"Steuerliche Freibetr\xe4ge lassen sich oft alle 10 Jahre erneut nutzen; fr\xfchzeitige \xdcbertragungen schaffen Klarheit und k\xf6nnen Kosten senken."},{heading:"Welche Risiken und Nachteile gibt es?",body:["Unklare Regelungen f\xfchren h\xe4ufig zu Konflikten.","Falsche Bewertungen oder Fristvers\xe4umnisse verursachen unn\xf6tige Steuerlast.","Nie\xdfbrauch- oder R\xfcckforderungsklauseln sind komplex und m\xfcssen sorgf\xe4ltig gestaltet werden."]},{heading:"Rolle in einem diversifizierten Portfolio",body:"Verm\xf6gens\xfcbertragung ist keine reine Anlagestrategie, sondern eine \xfcbergreifende Planungsaufgabe \u2014 sie steht neben der eigentlichen Portfoliostruktur."},{heading:"Worauf sollte man achten?",body:"Auf fr\xfchzeitige Planung, saubere rechtliche Gestaltung, Einbindung aller Beteiligten und den Blick auf die eigenen finanziellen Bed\xfcrfnisse zu Lebzeiten."}])]}],a=e=>s.find(n=>n.slug===e)||null,u=(e,n)=>{const i=a(e);if(!i)return null;const t=i.topics.find(e=>e.slug===n);return t?{category:i,topic:t}:null}}}]);